:"payArbitrationFee","outputs":[],"stateMutability":"payable","type":"function"},{"inputs":[{"internalType":"uint256","name":"","type":"uint256"}],"name":"postedHiredTalents","outputs":[{"internalType":"uint256","name":"talentId","type":"uint256"},{"internalType":"address","name":"freelancer","type":"address"},{"internalType":"uint256","name":"basePayment","type":"uint256"},{"internalType":"string","name":"title","type":"string"},{"internalType":"string","name":"description","type":"string"},{"internalType":"string","name":"category","type":"string"},{"internalType":"string","name":"bannerImageHash","type":"string"},{"internalType":"uint256","name":"minimumNoticeTime","type":"uint256"},{"internalType":"uint256","name":"averageWorkDuration","type":"uint256"},{"internalType":"uint256","name":"createdAt","type":"uint256"}],"stateMutability":"view","type":"function"},{"inputs":[],"name":"postedHiredTalentsCounter","outputs":[{"internalType":"uint256","name":"","type":"uint256"}],"stateMutability":"view","type":"function"},{"inputs":[{"internalType":"uint256","name":"_talentId","type":"uint256"},{"internalType":"uint256","name":"_hiredTalentId","type":"uint256"},{"internalType":"uint8","name":"_rating","type":"uint8"}],"name":"rateHiredTalent","outputs":[],"stateMutability":"nonpayable","type":"function"},{"inputs":[{"internalType":"uint256","name":"_talentId","type":"uint256"},{"internalType":"uint256","name":"_hiredTalentId","type":"uint256"},{"internalType":"string","name":"_comment","type":"string"}],"name":"rejectHiredTalent","outputs":[],"stateMutability":"nonpayable","type":"function"},{"inputs":[{"internalType":"uint256","name":"_talentId","type":"uint256"},{"internalType":"uint256","name":"_hiredTalentId","type":"uint256"},{"internalType":"string","name":"_metaEvidenceURI","type":"string"},{"internalType":"string","name":"_initialEvidenceURI","type":"string"},{"internalType":"string","name":"_reason","type":"string"}],"name":"startDispute","outputs":[],"stateMut